/// <summary>
/// CB521_ExciseRegister
/// UI builder class to work on lookup
/// </summary>
class METNature3040ReportUIBuilder extends SrsReportDataContractUIBuilder
{
    METNature3040ReportContract contract;
    DialogField                 dialogNature30Num;
    METNAT3040                  metNat3040;
    DialogField                 dialogSite;
    DialogField                 CPI;
    DialogField                 lastRunDateTime;
    DialogField                 fromDate;
    DialogField                 toDate;
    DialogField                 sitespecific;
    DialogField                 bondNumber;      
    SRSReportName               reportName;

}

Method.Source:
    /// <summary>
    /// Build method for control build
    /// </summary>
    public void build()
    {
        METExciseInformationTable           metExciseInformationTable;
        METReportRunHistory                 lastSucessfulReportRun;

        contract = this.dataContractObject();
        dialogNature30Num = this.addDialogField(methodStr(METNature3040ReportContract, parmNat30Number), contract);

        CPI = this.addDialogField(methodStr(METNature3040ReportContract, parmCPI), contract);

        sitespecific = this.addDialogField(methodStr(METNature3040ReportContract, parmSiteSpecific), contract);
        sitespecific = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(METNature3040ReportContract, parmSiteSpecific));
        sitespecific.registerOverrideMethod(methodStr(FormCheckBoxControl, modified), methodStr(METNature3040ReportUIBuilder, siteSpecific_modified), this);

        dialogSite = this.addDialogField(methodStr(METNature3040ReportContract, parmSite), contract);
        dialogSite = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(METNature3040ReportContract, parmSite));
        dialogSite.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METNature3040ReportUIBuilder, site_modified), this);
        
        
        fromDate = this.addDialogField(methodStr(METNature3040ReportContract, parmFromDate), contract);
        fromDate = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(METNature3040ReportContract, parmFromDate));
        fromDate.registerOverrideMethod(methodStr(FormDateControl, validate), methodStr(METNature3040ReportUIBuilder, validate_fromDate), this);

        toDate = this.addDialogField(methodStr(METNature3040ReportContract, parmToDate), contract);
        toDate = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(METNature3040ReportContract, parmToDate));
        toDate.registerOverrideMethod(methodStr(FormDateControl, validate), methodStr(METNature3040ReportUIBuilder, validate_ToDate), this);

        lastRunDateTime = this.addDialogField(methodStr(METNature3040ReportContract, parmLastRunDateTime), contract);
        lastRunDateTime = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(METNature3040ReportContract, parmLastRunDateTime));

        dialogNature30Num = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(METNature3040ReportContract, parmNat30Number));
        dialogNature30Num.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(MetNature3040ReportUIBuilder, nat3040NumLookup), this);

        dialogSite = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(METNature3040ReportContract, parmSite));
        dialogSite.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METNature3040ReportUIBuilder, siteLookup), this);

        if (this.controller().parmArgs().menuItemName() == menuItemActionStr(METNature30Report))
        {
            reportName = ssrsReportStr(METNature3040Report, Nature30);
            select firstonly metExciseInformationTable
                order by Nat3040ReportNumber desc
                where metExciseInformationTable.NAT3040 == METNAT3040::NAT30    &&
                        metExciseInformationTable.Nat3040ReportNumber != '';

            dialogNature30Num.label("@MET:Nat30Number");
            contract.parmMETNat3040(METNAT3040::NAT30);
            dialogNature30Num.value(metExciseInformationTable.Nat3040ReportNumber);
        }
        else if (this.controller().parmArgs().menuItemName() == menuItemActionStr(METNature40Report))
        {
            reportName = ssrsReportStr(METNature3040Report, Nature40);
            select firstonly metExciseInformationTable
                order by Nat3040ReportNumber desc
                where metExciseInformationTable.NAT3040 == METNAT3040::NAT40    &&
                        metExciseInformationTable.Nat3040ReportNumber != '';

            dialogNature30Num.label("@MET:Nat40Num");
            contract.parmMETNat3040(METNAT3040::NAT40);
            dialogNature30Num.value(metExciseInformationTable.Nat3040ReportNumber);
        }
        
        NoYesId         siteSpecificValue = contract.parmSiteSpecific();
        InventSiteId    site = contract.parmSite();
        
        select firstonly LastSuccessfulRun from lastSucessfulReportRun
            where lastSucessfulReportRun.SRSReportName == reportName &&
                  lastSucessfulReportRun.SiteSpecific == siteSpecificValue &&
                  lastSucessfulReportRun.Site == site;

        if (lastSucessfulReportRun)
        {
            lastRunDateTime.value(lastSucessfulReportRun.LastSuccessfulRun);
            contract.parmLastRunDateTime(lastSucessfulReportRun.LastSuccessfulRun);
        }
        else
        {
            metExciseInformationTable = null;

            select firstonly1 CreatedDateTime from metExciseInformationTable
                order by CreatedDateTime;

            if (metExciseInformationTable.CreatedDateTime)
            {
                contract.parmLastRunDateTime(metExciseInformationTable.CreatedDateTime);
                lastRunDateTime.value(metExciseInformationTable.CreatedDateTime);
            }
            else
            {
                contract.parmLastRunDateTime(DateTimeUtil::minValue());
                lastRunDateTime.value(DateTimeUtil::minValue());
            }
        }
        
    }

    /// <summary>
    /// site specific modified method to enable/disable site control
    /// </summary>
    /// <param name = "_siteSpecific">formCheckBoxControl</param>
    /// <returns>boolean</returns>
    public boolean siteSpecific_modified(FormcheckBoxControl    _siteSpecific)
    {
        boolean ok = true;
        METReportRunHistory                 lastSucessfulReportRun;
        METExciseInformationTable           metExciseInformationTable;

        if (_siteSpecific.value() == NoYes::Yes)
        {
            dialogSite.value('');
            dialogSite.enabled(false);
        }
        else
        {
            dialogSite.enabled(true);
        }

        NoYesId         siteSpecificValue = contract.parmSiteSpecific();
        InventSiteId    site = contract.parmSite();
        
        select firstonly LastSuccessfulRun from lastSucessfulReportRun
            where lastSucessfulReportRun.SRSReportName == reportName &&
                  lastSucessfulReportRun.SiteSpecific == siteSpecificValue &&
                  lastSucessfulReportRun.Site == site;

        if (lastSucessfulReportRun)
        {
            lastRunDateTime.value(lastSucessfulReportRun.LastSuccessfulRun);
            contract.parmLastRunDateTime(lastSucessfulReportRun.LastSuccessfulRun);
        }
        else
        {
            metExciseInformationTable = null;

            select firstonly1 CreatedDateTime from metExciseInformationTable
                order by CreatedDateTime;

            if (metExciseInformationTable.CreatedDateTime)
            {
                contract.parmLastRunDateTime(metExciseInformationTable.CreatedDateTime);
                lastRunDateTime.value(metExciseInformationTable.CreatedDateTime);
            }
            else
            {
                contract.parmLastRunDateTime(DateTimeUtil::minValue());
                lastRunDateTime.value(DateTimeUtil::minValue());
            }
        }

        return ok;
    }

    /// <summary>
    /// site modified method to set bond number based on site selected
    /// </summary>
    /// <param name = "_site">Site</param>
    /// <returns>boolean</returns>
    public boolean site_modified(FormStringControl    _site)
    {
        boolean ok = true;
        METReportRunHistory                 lastSucessfulReportRun;
        METExciseInformationTable           metExciseInformationTable;

        if (_site.valueStr())
        {
            contract.parmBondNumber(InventSite::find(_site.valueStr()).METBondNumber);
            contract.parmSiteName(InventSite::find(_site.valueStr()).Name);
        }
        else
        {
            contract.parmBondNumber('');
            contract.parmSiteName('');
        }

        NoYesId         siteSpecificValue = contract.parmSiteSpecific();
        InventSiteId    site = contract.parmSite();
        
        select firstonly LastSuccessfulRun from lastSucessfulReportRun
            where lastSucessfulReportRun.SRSReportName == reportName &&
                  lastSucessfulReportRun.SiteSpecific == siteSpecificValue &&
                  lastSucessfulReportRun.Site == site;

        if (lastSucessfulReportRun)
        {
            lastRunDateTime.value(lastSucessfulReportRun.LastSuccessfulRun);
            contract.parmLastRunDateTime(lastSucessfulReportRun.LastSuccessfulRun);
        }
        else
        {
            metExciseInformationTable = null;

            select firstonly1 CreatedDateTime from metExciseInformationTable
                order by CreatedDateTime;

            if (metExciseInformationTable.CreatedDateTime)
            {
                contract.parmLastRunDateTime(metExciseInformationTable.CreatedDateTime);
                lastRunDateTime.value(metExciseInformationTable.CreatedDateTime);
            }
            else
            {
                contract.parmLastRunDateTime(DateTimeUtil::minValue());
                lastRunDateTime.value(DateTimeUtil::minValue());
            }
        }

        return ok;
    }

    /// <summary>
    /// Validate from date method
    /// </summary>
    /// <param name = "_formDateControl">Date control</param>
    /// <returns>boolean</returns>
    public boolean validate_fromDate(FormDateControl    _formDateControl)
    {
        boolean ok = true;

        if (_formDateControl.dateValue() <= DateTimeUtil::date(lastRunDateTime.value()))
        {
            ok = checkFailed("@MET:FromDateNat3040");
        }

        if (toDate.value() && _formDateControl.dateValue() > toDate.value())
        {
            ok = checkFailed("@MET:ToDateNat3040");
        }

        return ok;
    }

    /// <summary>
    /// validate to date method
    /// </summary>
    /// <param name = "_formDateControl">date control</param>
    /// <returns>boolean</returns>
    public boolean validate_ToDate(FormDateControl    _formDateControl)
    {
        boolean ok = true;

        if (fromDate.value() && fromDate.value() >_formDateControl.dateValue())
        {
            ok = checkFailed("@MET:ToDateNat3040");
        }

        return ok;
    }

    /// <summary>
    /// Lookup method for nat 3040 number
    /// </summary>
    /// <param name = "_nat30Num">Form control reference</param>
    private void nat3040NumLookup(FormStringControl _nat30Num)
    {
        Query                   query = new Query();
        QueryBuildDataSource    metExciseInformationTableQbds;
        SysTableLookup          sysTableLookup;

        sysTableLookup = SysTableLookup::newParameters(tableNum(METExciseInformationTable), _nat30Num);
        sysTableLookup.addLookupfield(fieldNum(METExciseInformationTable, Nat3040ReportNumber));

        metExciseInformationTableQbds = query.addDataSource(tableNum(METExciseInformationTable));
        metExciseInformationTableQbds.orderMode(OrderMode::GroupBy);
        metExciseInformationTableQbds.addGroupByField(fieldNum(METExciseInformationTable, Nat3040ReportNumber));


        metExciseInformationTableQbds.addRange(fieldNum(METExciseInformationTable, Nat3040ReportNumber)).value(SysQuery::valueNotEmptyString());

        if (contract.parmMETNat3040() == METNat3040::NAT30)
        {
            metExciseInformationTableQbds.addRange(fieldNum(METExciseInformationTable, NAT3040)).value(SysQuery::value(METNAT3040::NAT30));
        }

        else if (contract.parmMETNat3040() == METNat3040::NAT40)
        {
            metExciseInformationTableQbds.addRange(fieldNum(METExciseInformationTable, NAT3040)).value(SysQuery::value(METNAT3040::NAT40));
        }
        sysTableLookup.parmUseLookupValue(false);


        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    /// Multi-select lookup for InventSite. Selected site ids are stored in the contract's site list
    /// and displayed as a comma-separated string in the dialog control.
    /// </summary>
    /// <param name = "_control">Form control reference</param>
    private void siteLookup(FormStringControl _control)
    {
        Query                             query = new Query();
        QueryBuildDataSource              qbds;
        SysTableLookup                   sysTableLookup = SysTableLookup::newParameters(tableNum(InventSite), _control);
       

        // Build the query for InventSite
        qbds = query.addDataSource(tableNum(InventSite));
        // Optionally filter by current company or active sites - adjust ranges as required
        qbds.addRange(fieldNum(InventSite, METBondedWarehouse)).value(queryValue(NoYes::Yes));

        sysTableLookup.addLookupfield(fieldNum(InventSite, SiteId), true);
        sysTableLookup.addLookupfield(fieldNum(InventSite, Name));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
